<script setup>
import { computed, ref, watch } from 'vue';
const props=defineProps({mode:{type:String,required:true},completado:{type:Boolean,default:false}});const emit=defineEmits(['hablar','practicar']);
const paso=ref(1),escenaId=ref(0),variante=ref(0),retoIdx=ref(0),elegida=ref(null),aciertos=ref(new Set());
const preguntas=[{icono:'📍',palabra:'Where',objetivo:'lugar',respuesta:'The party is at Ana’s house.',directa:'Where is the party?',indirecta:'Could you tell me where the party is?'},{icono:'🕗',palabra:'When',objetivo:'momento',respuesta:'The movie starts at 8 PM.',directa:'When does the movie start?',indirecta:'Do you know when the movie starts?'},{icono:'🎁',palabra:'What',objetivo:'cosa',respuesta:'She bought a book.',directa:'What did she buy?',indirecta:'Could you tell me what she bought?'},{icono:'👩',palabra:'Who',objetivo:'persona',respuesta:'Marta called me.',directa:'Who called me?',indirecta:'Do you know who called me?'},{icono:'🤔',palabra:'Why',objetivo:'razón',respuesta:'They left because it was late.',directa:'Why did they leave?',indirecta:'Could you tell me why they left?'},{icono:'🚌',palabra:'How',objetivo:'manera',respuesta:'He travels by bus.',directa:'How does he travel?',indirecta:'Do you know how he travels?'}];
const tags=[{icono:'🌤️',afirmacion:"It's a beautiful day",tag:"isn't it?",tipo:'positiva → tag negativa'},{icono:'🍲',afirmacion:'You made dinner',tag:"didn't you?",tipo:'positiva → tag negativa'},{icono:'📚',afirmacion:'They like this book',tag:"don't they?",tipo:'positiva → tag negativa'},{icono:'🚗',afirmacion:"She can't drive",tag:'can she?',tipo:'negativa → tag positiva'},{icono:'🏠',afirmacion:"We aren't late",tag:'are we?',tipo:'negativa → tag positiva'}];
const escena=computed(()=>props.mode==='tags'?tags[escenaId.value%tags.length]:preguntas[escenaId.value%preguntas.length]);
const fraseTag=computed(()=>`${escena.value.afirmacion}, ${escena.value.tag}`);
const meta=computed(()=>({wh:{icono:'❓',sobre:'INFORMACIÓN PRECISA',titulo:'Wh-questions',bajada:'Elegí la palabra interrogativa según la información que necesitás.',tabs:['Apuntá la pregunta','Orden de palabras','Reto Wh-']},tags:{icono:'🪃',sobre:'BUSCAR CONFIRMACIÓN',titulo:'Question tags',bajada:'Agregá una mini-pregunta al final para confirmar o buscar acuerdo.',tabs:['Completá el rebote','Polaridad y auxiliar','Reto de confirmación']},indirect:{icono:'💬',sobre:'PREGUNTAR CON CORTESÍA',titulo:'Preguntas indirectas',bajada:'Suavizá una pregunta y devolvé el orden interno a sujeto + verbo.',tabs:['Suavizá la pregunta','El cambio de orden','Reto indirecto']}}[props.mode]));
const retos=computed(()=>({wh:[{i:'📍',f:'___ is the nearest store?',r:'Where',o:['What','Where','When','Who'],a:'Where pregunta por un lugar.'},{i:'🤔',f:'___ did you leave early?',r:'Why',o:['How many','Who','Why','Where'],a:'Why pregunta por una razón.'},{i:'👤',f:'___ called you last night?',r:'Who',o:['Who','Who did','Where','What did'],a:'Who es el sujeto; no necesita did aquí.'},{i:'🚌',f:'___ do you get home?',r:'How',o:['What','How','When many','Who'],a:'How pregunta por la manera.'}],tags:[{i:'🌤️',f:"It's warm today, ___",r:"isn't it?",o:["isn't it?",'is it?',"doesn't it?",'does it?'],a:'La afirmación con is lleva tag negativa con is.'},{i:'🍲',f:'You cooked dinner, ___',r:"didn't you?",o:["don't you?","didn't you?",'did you?',"aren't you?"],a:'El pasado simple usa did en la tag.'},{i:'🚗',f:"She can't drive, ___",r:'can she?',o:["can't she?",'does she?','can she?','is she?'],a:'La oración negativa recibe una tag positiva.'},{i:'📚',f:'They like this book, ___',r:"don't they?",o:["aren't they?","didn't they?","don't they?",'do they?'],a:'Presente simple con they usa do.'}],indirect:[{i:'📍',f:'Do you know ___?',r:'where the station is',o:['where is the station','where the station is','the station where is','is where the station'],a:'Dentro de la pregunta indirecta usamos sujeto + verbo.'},{i:'🕗',f:'Could you tell me ___?',r:'what time it is',o:['what time is it','what time it is','is it what time','what is it time'],a:'La inversión desaparece después de la introducción.'},{i:'❓',f:'I wonder ___ she is home.',r:'if',o:['does','if','is','that does'],a:'If introduce una pregunta indirecta de sí/no.'},{i:'🎬',f:'Do you know when ___?',r:'the movie starts',o:['does the movie start','the movie starts','starts the movie','the movie does start'],a:'Usamos orden afirmativo: the movie starts.'}]}[props.mode]));
const reto=computed(()=>retos.value[retoIdx.value]),correcta=computed(()=>elegida.value===reto.value.r);
function escuchar(t){emit('hablar',t,1)}function responder(o){elegida.value=o;if(o===reto.value.r)aciertos.value=new Set([...aciertos.value,retoIdx.value])}function siguiente(){retoIdx.value=(retoIdx.value+1)%retos.value.length;elegida.value=null}watch(()=>props.mode,()=>{paso.value=1;escenaId.value=0;variante.value=0;retoIdx.value=0;elegida.value=null;aciertos.value=new Set()});
</script>

<template><section class="questions" :class="`questions--${mode}`"><aside class="hero"><span>{{meta.icono}}</span><div><small>ADULTO ESTÁNDAR · {{meta.sobre}}</small><h2>{{meta.titulo}}</h2><p>{{meta.bajada}}</p></div><div class="question-mark"><b>ASK</b><i>→</i><span>?</span></div></aside><nav><button v-for="(tab,i) in meta.tabs" :key="tab" :class="{active:paso===i+1}" @click="paso=i+1"><b>0{{i+1}}</b><span>{{tab}}</span></button></nav>
<main v-if="paso===1 && mode==='wh'"><header><small>WH 1</small><h3>Apuntá a la información</h3><p>Elegí qué dato querés conocer y escuchá la pregunta correspondiente.</p></header><div class="wh-grid"><button v-for="(x,i) in preguntas" :key="x.palabra" :class="{active:escenaId===i}" @click="escenaId=i"><span>{{x.icono}}</span><b>{{x.palabra}}</b><small>{{x.objetivo}}</small></button></div><article class="result"><small>RESPUESTA POSIBLE</small><p>{{escena.respuesta}}</p><i>↓ preguntá por {{escena.objetivo}} ↓</i><strong>{{escena.directa}}</strong><button @click="escuchar(escena.directa)">🔊 Escuchar</button></article></main>
<main v-else-if="paso===1 && mode==='tags'"><header><small>TAGS 1</small><h3>Completá el rebote</h3><p>La mini-pregunta repite el auxiliar y cambia de positivo a negativo o al revés.</p></header><div class="tag-picker"><button v-for="(x,i) in tags" :key="x.afirmacion" :class="{active:escenaId===i}" @click="escenaId=i">{{x.icono}} <b>{{x.afirmacion}}</b></button></div><article class="tag-stage"><span>{{escena.icono}}</span><div><small>LO QUE CREÉS</small><b>{{escena.afirmacion}},</b></div><i>↪</i><div><small>CONFIRMACIÓN</small><strong>{{escena.tag}}</strong></div><button @click="escuchar(fraseTag)">🔊 {{fraseTag}}</button></article></main>
<main v-else-if="paso===1"><header><small>INDIRECTAS 1</small><h3>Suavizá la pregunta</h3><p>Elegí una pregunta y alterná entre la forma directa y una entrada más cortés.</p></header><div class="wh-grid"><button v-for="(x,i) in preguntas" :key="x.palabra" :class="{active:escenaId===i}" @click="escenaId=i"><span>{{x.icono}}</span><b>{{x.palabra}}</b><small>{{x.objetivo}}</small></button></div><div class="softener"><button :class="{active:variante===0}" @click="variante=0">DIRECTA</button><i>→</i><button :class="{active:variante===1}" @click="variante=1">MÁS CORTÉS</button></div><article class="result"><span>{{variante?'🙂':'❓'}}</span><small>{{variante?'PREGUNTA INDIRECTA':'PREGUNTA DIRECTA'}}</small><strong>{{variante?escena.indirecta:escena.directa}}</strong><button @click="escuchar(variante?escena.indirecta:escena.directa)">🔊 Escuchar</button></article></main>
<main v-else-if="paso===2 && mode==='wh'"><header><small>WH 2</small><h3>Orden de palabras</h3><p>La mayoría usa auxiliar; cuando who o what es el sujeto, no se agrega do/did.</p></header><div class="formula"><b>WH</b><i>＋</i><strong>auxiliary</strong><i>＋</i><b>subject</b><i>＋</i><span>base verb?</span></div><div class="compare"><article><small>WH = INFORMACIÓN</small><b>Where <mark>do you live</mark>?</b><p>auxiliar + sujeto + verbo</p></article><article><small>WHO = SUJETO</small><b>Who <mark>called you</mark>?</b><p>sin auxiliar adicional</p></article></div></main>
<main v-else-if="paso===2 && mode==='tags'"><header><small>TAGS 2</small><h3>Polaridad y auxiliar</h3><p>Repetí el auxiliar y cambiá la polaridad.</p></header><div class="polarity"><article><span>＋</span><b>You're ready,</b><strong>aren't you?</strong></article><i>↔</i><article><span>−</span><b>You aren't tired,</b><strong>are you?</strong></article></div><div class="aux-map"><span><b>is</b> → isn't it?</span><span><b>are</b> → aren't they?</span><span><b>past</b> → didn't you?</span><span><b>can</b> → can't she?</span></div></main>
<main v-else-if="paso===2"><header><small>INDIRECTAS 2</small><h3>El cambio de orden</h3><p>La primera parte ya funciona como pregunta; la segunda vuelve al orden afirmativo.</p></header><div class="order-change"><article><small>DIRECTA</small><b>Where <mark>is the station</mark>?</b></article><i>→</i><article><small>INDIRECTA</small><b>Could you tell me where <mark>the station is</mark>?</b></article></div><aside class="note"><b>Preguntas de sí/no:</b> usá <i>if</i> o <i>whether</i>: “Do you know if the store is open?”</aside></main>
<main v-else><header class="challenge-head"><div><small>{{meta.sobre}} · RETO</small><h3>{{meta.tabs[2]}}</h3><p>Identificá la información, el auxiliar y el orden correcto.</p></div><b>{{aciertos.size}}/{{retos.length}}</b></header><article class="challenge"><span>{{reto.i}}</span><button @click="escuchar(reto.f.replace('___',reto.r))">{{reto.f}} 🔊</button><div><button v-for="o in reto.o" :key="o" :class="{ok:elegida&&o===reto.r,bad:elegida===o&&o!==reto.r}" @click="responder(o)">{{o}}</button></div><p v-if="elegida"><b>{{correcta?'✓ Pregunta natural':'↻ Revisá el orden'}}</b> {{reto.a}}</p><button v-if="correcta" class="next" @click="siguiente">Siguiente pregunta →</button></article></main><button class="practice" :disabled="completado" @click="emit('practicar')">{{completado?'✓ Ejercicios ya acreditados':'Practicar ejercicios del workbook →'}}</button></section></template>

<style scoped>
.questions{display:grid;gap:1rem;--accent:#526fa3;--soft:#ebf2fc;--warm:#fff2df}.questions--tags{--accent:#8b5d88;--soft:#f7edf5;--warm:#edf7f2}.questions--indirect{--accent:#3d786d;--soft:#eaf6f2;--warm:#fff4df}.hero,main{padding:1rem;border:1px solid var(--color-borde);border-radius:var(--radio-panel);background:var(--color-superficie)}.hero{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:.8rem;background:linear-gradient(135deg,var(--soft),var(--warm))}.hero>span{font-size:2.7rem}.hero h2,main h3{margin:.15rem 0}.hero p,main header p{margin:.25rem 0;color:var(--color-texto-secundario)}small{font-size:.62rem;font-weight:900;letter-spacing:.08em;color:var(--accent)}.question-mark{display:flex;align-items:center;gap:.35rem;padding:.6rem;border:1px dashed var(--accent);border-radius:10px;color:var(--accent);font-size:.7rem}.question-mark span{font-size:1.3rem}nav{display:grid;grid-template-columns:repeat(3,1fr);gap:.5rem}nav button{display:flex;gap:.5rem;padding:.7rem;border:1px solid var(--color-borde);border-radius:12px;background:var(--color-superficie);text-align:left}nav button b{color:var(--accent)}nav button.active,.wh-grid button.active,.tag-picker button.active,.softener button.active{border-color:var(--accent)!important;background:var(--soft)!important}.wh-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:.4rem}.wh-grid button{display:flex;flex-direction:column;align-items:center;padding:.6rem;border:1px solid var(--color-borde);border-radius:10px;background:var(--color-superficie)}.wh-grid span{font-size:1.5rem}.result{display:flex;flex-direction:column;align-items:center;gap:.25rem;margin-top:.8rem;padding:1rem;border-radius:15px;background:linear-gradient(145deg,var(--soft),var(--warm));text-align:center}.result p{margin:.2rem;color:var(--color-texto-secundario)}.result>span{font-size:2rem}.result strong{font:italic 1.15rem Georgia}.result button,.tag-stage button{padding:.5rem .7rem;border:0;border-radius:var(--radio-boton);background:var(--accent);color:#fff}.tag-picker{display:flex;flex-wrap:wrap;gap:.4rem}.tag-picker button{padding:.55rem;border:1px solid var(--color-borde);border-radius:9px;background:var(--color-superficie)}.tag-stage{display:grid;grid-template-columns:auto 1fr auto 1fr;align-items:center;gap:.7rem;margin-top:.8rem;padding:1rem;border-radius:15px;background:linear-gradient(145deg,var(--soft),var(--warm))}.tag-stage>span{font-size:2rem}.tag-stage>div{display:flex;flex-direction:column}.tag-stage strong{color:var(--accent)}.tag-stage button{grid-column:1/-1;justify-self:center}.softener{display:flex;justify-content:center;align-items:center;gap:.5rem;margin:.8rem}.softener button{padding:.55rem .8rem;border:1px solid var(--color-borde);border-radius:99px;background:var(--color-superficie);font-weight:900;color:var(--accent)}.formula{display:flex;justify-content:center;align-items:center;gap:.6rem;padding:1rem;border-radius:14px;background:var(--soft)}.formula strong{font:italic 1.15rem Georgia;color:var(--accent)}.compare,.polarity,.order-change{display:grid;grid-template-columns:1fr 1fr;gap:.7rem;margin-top:.8rem}.compare article,.polarity article,.order-change article{display:flex;flex-direction:column;padding:1rem;border:1px solid var(--color-borde);border-radius:13px;text-align:center}.compare mark,.order-change mark{padding:.1rem .25rem;border-radius:4px;background:#ffe6a7}.compare p{font-size:.7rem;color:var(--color-texto-tenue)}.polarity{grid-template-columns:1fr auto 1fr;align-items:center}.polarity article strong{color:var(--accent)}.aux-map{display:grid;grid-template-columns:repeat(4,1fr);gap:.4rem;margin-top:.7rem}.aux-map span{padding:.6rem;border-radius:9px;background:var(--soft);font-size:.72rem}.order-change{grid-template-columns:1fr auto 1fr;align-items:center}.note{margin-top:.7rem;padding:.7rem;border-left:4px solid var(--accent);border-radius:8px;background:var(--soft);font-size:.75rem}.challenge-head{display:flex;justify-content:space-between}.challenge-head>b{display:grid;place-items:center;width:48px;height:48px;border-radius:50%;background:var(--soft);color:var(--accent)}.challenge{max-width:650px;margin:auto;padding:1rem;border-radius:16px;background:linear-gradient(145deg,var(--soft),var(--warm));text-align:center}.challenge>span{font-size:2.7rem}.challenge>button{display:block;margin:.4rem auto;border:0;background:transparent;font:italic 1.08rem Georgia}.challenge>div{display:grid;grid-template-columns:1fr 1fr;gap:.4rem}.challenge>div button{padding:.6rem;border:1px solid var(--color-borde);border-radius:9px;background:var(--color-superficie)}.challenge .ok{border-color:var(--color-verde);background:var(--color-verde-suave)}.challenge .bad{border-color:var(--color-rojo);background:var(--color-rojo-suave)}.next{padding:.55rem .8rem!important;background:var(--accent)!important;color:#fff!important}.practice{width:100%;padding:.8rem;border:0;border-radius:var(--radio-boton);background:var(--accent);color:#fff;font-weight:800}.practice:disabled{background:var(--color-verde)}
@media(max-width:680px){.hero{grid-template-columns:auto 1fr}.question-mark{grid-column:1/-1;justify-content:center}nav,.compare,.challenge>div{grid-template-columns:1fr}.wh-grid{grid-template-columns:repeat(3,1fr)}.polarity,.order-change{grid-template-columns:1fr}.polarity>i,.order-change>i{text-align:center;transform:rotate(90deg)}.aux-map{grid-template-columns:1fr 1fr}.formula{flex-wrap:wrap}}@media(max-width:420px){.wh-grid,.aux-map{grid-template-columns:1fr 1fr}.tag-stage{grid-template-columns:auto 1fr}.tag-stage>i{display:none}}
</style>
